<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { message } from 'ant-design-vue'
import { usePortalStore } from '@/stores/portal'
import { iamMessage } from '@/services/iamAccess'
import { shiftOverview, shiftEmployees, boundShifts, shiftCommand, type ShiftOverview, type ShiftEmployee, type ShiftRule } from '@/services/attendanceShifts'
const portal=usePortalStore(),caps=computed(()=>portal.apps.find(app=>app.id==='attendance')?.accessCapabilities||[]),data=ref<ShiftOverview|null>(null),department=ref(''),employees=ref<ShiftEmployee[]>([]),employee=ref(''),codes=ref<string[]>([]),error=ref(''),busy=ref(false),formOpen=ref(false),editing=ref<ShiftRule|null>(null)
const form=reactive({rule_name:'',shift_type:'行政班',start_time:'08:00',end_time:'17:00',late_after:'08:01',min_hours:8,effective_from:''})
const rules=computed(()=>data.value?.rules.filter(row=>!department.value||row.department===department.value)||[])
async function load(){busy.value=true;error.value='';try{data.value=await shiftOverview();if(!department.value)department.value=data.value.departments[0]||'';await loadEmployees()}catch(e){error.value=iamMessage(e)}finally{busy.value=false}}
async function loadEmployees(){employee.value='';codes.value=[];employees.value=[];if(!department.value||!caps.value.includes('attendance.schedule.read'))return;try{employees.value=await shiftEmployees(department.value)}catch(e){error.value=iamMessage(e)}}
async function loadBound(){codes.value=[];if(!employee.value)return;try{codes.value=await boundShifts(employee.value)}catch(e){error.value=iamMessage(e)}}
function edit(row?:ShiftRule){editing.value=row||null;Object.assign(form,{rule_name:row?.rule_name||'',shift_type:row?.shift_type||'行政班',start_time:row?.start_time||'08:00',end_time:row?.end_time||'17:00',late_after:row?.late_after||'08:01',min_hours:row?.min_hours||8,effective_from:''});formOpen.value=true}
async function save(){busy.value=true;error.value='';try{await shiftCommand(editing.value?'update_shift_rule':'create_shift_rule',editing.value?{rule_name:editing.value.name,updates:JSON.stringify({start_time:form.start_time,end_time:form.end_time,late_after:form.late_after,min_hours:form.min_hours})}:{...form,department:department.value,effective_from:form.effective_from||undefined});formOpen.value=false;message.success('班次版本已保存。历史版本保留。');await load()}catch(e){error.value=iamMessage(e)}finally{busy.value=false}}
const pending=ref<{method:string;params:Record<string,unknown>;title:string;description:string}|null>(null)
function status(row:ShiftRule){pending.value={method:'set_rule_status',params:{rule_name:row.name,status:row.status==='停用'?'生效':'停用'},title:row.status==='停用'?'恢复班次规则':'停用班次规则',description:'创建明日起生效的新版本，历史规则保留。'}}
function remove(row:ShiftRule){pending.value={method:'delete_shift_rule',params:{rule_name:row.name},title:'删除未引用的草稿规则',description:'仅无后继版本且无员工绑定的草稿允许删除。'}}
function bind(){pending.value={method:'bind_employee_shifts',params:{employee:employee.value,shift_rules:JSON.stringify(codes.value)},title:'确认安排员工班次',description:'仅替换所选员工的固定班次绑定。第一项为主班次；未选择班次会清除该员工的固定绑定。'}}
async function confirm(){if(!pending.value||busy.value)return;busy.value=true;error.value='';try{await shiftCommand(pending.value.method,pending.value.params);pending.value=null;message.success('班次操作完成。');await load()}catch(e){error.value=iamMessage(e)}finally{busy.value=false}}
onMounted(load)
</script>
<template><section class="shifts product-page app-product-page"><header class="glass-hero"><h1>班次与排班</h1><p>按负责公司维护现有班次版本与员工绑定。历史规则、生效日期及原生校验保留。</p></header><section class="glass-surface section-panel"><a-alert v-if="error" type="warning" show-icon :message="error"/><a-space wrap><a-select v-model:value="department" :options="data?.departments.map(value=>({value,label:value}))" aria-label="班次部门" style="min-width:240px" @change="loadEmployees"/><a-button :loading="busy" @click="load">读取最新配置</a-button><a-button v-if="caps.includes('attendance.shift.manage')" :disabled="!department" @click="edit()">新增班次</a-button></a-space><a-table :data-source="rules" row-key="name" :pagination="{pageSize:8}"><a-table-column title="班次" data-index="rule_name"/><a-table-column title="类型" data-index="shift_type"/><a-table-column title="开始" data-index="start_time"/><a-table-column title="结束" data-index="end_time"/><a-table-column title="生效日期" data-index="effective_from"/><a-table-column title="状态" data-index="status"/><a-table-column title="操作"><template #default="{record}"><a-space><a-button v-if="caps.includes('attendance.shift.manage')&&record.status!=='草稿'&&record.is_latest" @click="edit(record)">保存新版本</a-button><a-button v-if="caps.includes('attendance.shift.status')&&record.status!=='草稿'&&record.is_latest" @click="status(record)">{{record.status==='停用'?'恢复':'停用'}}</a-button><a-button v-if="caps.includes('attendance.shift.delete')&&record.status==='草稿'" danger @click="remove(record)">删除草稿</a-button></a-space></template></a-table-column></a-table></section><section v-if="caps.includes('attendance.schedule.read')" class="glass-surface section-panel"><h2>员工固定班次</h2><a-space wrap><a-select v-model:value="employee" :options="employees.map(row=>({value:row.name,label:row.employee_name+' · '+row.employee_number}))" aria-label="排班员工" style="min-width:260px" @change="loadBound"/><a-select v-model:value="codes" mode="multiple" :disabled="!employee||!caps.includes('attendance.schedule.bind')" :options="data?.bindable_rules.map(row=>({value:row.rule_code,label:row.rule_name+' · '+row.department}))" aria-label="员工班次" style="min-width:320px"/><a-button v-if="caps.includes('attendance.schedule.bind')" :disabled="!employee" @click="bind">核对班次安排</a-button></a-space><p>轮班日期排班在“规则与重算”中单独预览生成。系统策略及已有排班继续按现有优先级执行。</p></section><a-modal v-model:open="formOpen" :get-container="false" :title="editing?'保存班次新版本':'新增班次'" ok-text="保存" cancel-text="取消" :confirm-loading="busy" @ok="save"><a-alert v-if="error" type="warning" :message="error"/><a-form layout="vertical"><a-form-item label="规则名称"><a-input v-model:value="form.rule_name" :disabled="!!editing" :maxlength="80"/></a-form-item><a-form-item label="班次类型"><a-select v-model:value="form.shift_type" :disabled="!!editing" :options="data?.shift_types.map(value=>({value,label:value}))"/></a-form-item><a-form-item label="开始 / 结束 / 迟到界限"><a-space><a-input v-model:value="form.start_time" type="time"/><a-input v-model:value="form.end_time" type="time"/><a-input v-model:value="form.late_after" type="time"/></a-space></a-form-item><a-form-item label="最少工时"><a-input-number v-model:value="form.min_hours" :min="0" :max="24"/></a-form-item><a-form-item v-if="!editing" label="生效日期（空则明天）"><a-input v-model:value="form.effective_from" type="date"/></a-form-item><p v-else>新版本按原生规则于明日生效。</p></a-form></a-modal><a-modal :open="!!pending" :get-container="false" :title="pending?.title" ok-text="确认办理" cancel-text="返回核对" :confirm-loading="busy" @ok="confirm" @cancel="pending=null"><p>{{pending?.description}}</p><a-alert v-if="error" type="warning" :message="error"/></a-modal></section></template>
<style scoped>.shifts{display:grid;gap:20px}.glass-hero,.section-panel{padding:24px}.ant-alert{margin:16px 0}.ant-table-wrapper{margin-top:20px}</style>
